double BND_IntervalX::NormalizedParameterAt(double intervalParameter)
{
  double x;
  if (RH3DM_RhinoMath::IsValidDouble(intervalParameter))
  {
    if (m_t0 != m_t1)
    {
      x = ((intervalParameter == m_t1) ? 1.0 : (intervalParameter - m_t0) / (m_t1 - m_t0));
    }
    else
    {
      x = 0.0;
    }
  }
  else
  {
    x = RH3DM_RhinoMath::UnsetValue;
  }
  return x;
}

