double BND_Vector3dX::GetLengthHelper(double dx, double dy, double dz)
{
  if (!RH3DM_RhinoMath::IsValidDouble(dx) || !RH3DM_RhinoMath::IsValidDouble(dy) || !RH3DM_RhinoMath::IsValidDouble(dz))
  {
    return 0.0;
  }
  double len;
  double fx = std::abs(dx);
  double fy = std::abs(dy);
  double fz = std::abs(dz);
  if (fy >= fx && fy >= fz)
  {
    len = fx;
    fx = fy;
    fy = len;
  }
  else
  {
    if (fz >= fx && fz >= fy)
    {
      len = fx;
      fx = fz;
      fz = len;
    }
  }
  const double ON_DBL_MIN_cs = 2.2250738585072014e-308;
  if (fx > ON_DBL_MIN_cs)
  {
    len = 1.0 / fx;
    fy *= len;
    fz *= len;
    len = fx * std::sqrt(1.0 + fy * fy + fz * fz);
  }
  else
  {
    if (fx > 0.0 && RH3DM_RhinoMath::IsValidDouble(fx))
    {
      len = fx;
    }
    else
    {
      len = 0.0;
    }
  }
  return len;
}

