bool BND_LineX::Extend(double startLength, double endLength)
{
  if (!IsValid())
  {
    return false;
  }
  if (Length() == 0.0)
  {
    return false;
  }
  BND_Point3dX A = m_from;
  BND_Point3dX B = m_to;
  BND_Vector3dX tan = UnitTangent();
  if (startLength != 0.0)
  {
    A = m_from - startLength * tan;
  }
