bool BND_LineX::ExtendThroughPointSet(const std::vector<BND_Point3dX>& pts, double additionalLength)
{
  BND_Vector3dX unit = UnitTangent();
  if (!(unit).IsValid())
  {
    return false;
  }
  if (pts.empty())
  {
    return false;
  }
  double t0 = std::numeric_limits<double>::max();
  double t1 = std::numeric_limits<double>::lowest();
  for (BND_Point3dX pt : pts)
  {
    double t = ClosestParameter(pt);
    t0 = RH3DM_Min(t0, t);
    t1 = RH3DM_Max(t1, t);
  }
  if (t0 <= t1)
  {
    BND_Point3dX A = PointAt(t0) - (additionalLength * unit);
    BND_Point3dX B = PointAt(t1) + (additionalLength * unit);
    m_from = A;
    m_to = B;
  }
  else
  {
    BND_Point3dX A = PointAt(t0) + (additionalLength * unit);
    BND_Point3dX B = PointAt(t1) - (additionalLength * unit);
    m_from = A;
    m_to = B;
  }
  return true;
}

