BND_Point3dX BND_BoundingBoxX::ClosestPoint(BND_Point3dX point, bool includeInterior)
{
  double x0 = (m_min).m_x;
  double x1 = (m_max).m_x;
  double y0 = (m_min).m_y;
  double y1 = (m_max).m_y;
  double z0 = (m_min).m_z;
  double z1 = (m_max).m_z;
  if (x0 > x1)
  {
    x0 = (m_max).m_x;
    x1 = (m_min).m_x;
  }
  if (y0 > y1)
  {
    y0 = (m_max).m_y;
    y1 = (m_min).m_y;
  }
  if (z0 > z1)
  {
    z0 = (m_max).m_z;
    z1 = (m_min).m_z;
  }
  double x = (point).m_x;
  double y = (point).m_y;
  double z = (point).m_z;
  x = RH3DM_Max(x, x0);
  y = RH3DM_Max(y, y0);
  z = RH3DM_Max(z, z0);
  x = RH3DM_Min(x, x1);
  y = RH3DM_Min(y, y1);
  z = RH3DM_Min(z, z1);
  if (includeInterior)
  {
    return BND_Point3dX(x, y, z);
  }
  if ((point).m_x <= x0 || (point).m_x >= x1)
  {
    return BND_Point3dX(x, y, z);
  }
  if ((point).m_y <= y0 || (point).m_y >= y1)
  {
    return BND_Point3dX(x, y, z);
  }
  if ((point).m_z <= z0 || (point).m_z >= z1)
  {
    return BND_Point3dX(x, y, z);
  }
  std::vector<BND_Point3dX> C = GetCorners();
  std::vector<BND_PlaneX> faces = std::vector<BND_PlaneX>();
  if ((m_min).m_x != (m_max).m_x && (m_min).m_y != (m_max).m_y)
  {
    faces.push_back(BND_PlaneX(C[0], C[1], C[3]));
    faces.push_back(BND_PlaneX(C[4], C[5], C[7]));
  }
  if ((m_min).m_x != (m_max).m_x && (m_min).m_z != (m_max).m_z)
  {
    faces.push_back(BND_PlaneX(C[0], C[1], C[4]));
    faces.push_back(BND_PlaneX(C[3], C[2], C[7]));
  }
  if ((m_min).m_y != (m_max).m_y && (m_min).m_z != (m_max).m_z)
  {
    faces.push_back(BND_PlaneX(C[0], C[3], C[4]));
    faces.push_back(BND_PlaneX(C[1], C[2], C[5]));
  }
  double min_d = std::numeric_limits<double>::max();
  BND_Point3dX min_p = BND_Point3dX(x, y, z);
  for (BND_PlaneX face : faces)
  {
    double loc_d = std::abs((face).DistanceTo(BND_Point3dX(x, y, z)));
    if (loc_d < min_d)
    {
      min_d = loc_d;
      min_p = (face).ClosestPoint(BND_Point3dX(x, y, z));
    }
  }
  return min_p;
}

