bool BND_PlaneX::Rotate(double sinAngle, double cosAngle, BND_Vector3dX axis)
{
  bool rc = true;
  if (axis == ZAxis())
  {
    BND_Vector3dX x = cosAngle * XAxis() + sinAngle * YAxis();
    BND_Vector3dX y = cosAngle * YAxis() - sinAngle * XAxis();
    set_XAxis(x);
    set_YAxis(y);
  }
  else
  {
    BND_Point3dX origin_pt = Origin();
    rc = Rotate(sinAngle, cosAngle, axis, Origin());
    set_Origin(origin_pt);
  }
  return rc;
}

