bool BND_PlaneX::Rotate(double sinAngle, double cosAngle, BND_Vector3dX axis, BND_Point3dX centerOfRotation)
{
  if (centerOfRotation == Origin())
  {
    BND_TransformX rot = BND_TransformX::Rotation(sinAngle, cosAngle, axis, BND_Point3dX::Origin());
    set_XAxis(rot * XAxis());
    set_YAxis(rot * YAxis());
    set_ZAxis(rot * ZAxis());
    return true;
  }
  BND_TransformX rot2 = BND_TransformX::Rotation(sinAngle, cosAngle, axis, centerOfRotation);
  return Transform(rot2);
}

