bool BND_SphereX::ClosestParameter(BND_Point3dX testPoint, double& longitudeRadians, double& latitudeRadians)
{
  longitudeRadians = 0.0;
  latitudeRadians = 0.0;
  if (!(testPoint).IsValid())
  {
    return false;
  }
  if (!IsValid())
  {
    return false;
  }
  if (testPoint == (m_plane).Origin())
  {
    return false;
  }
  double u;
  double v;
  if (!(m_plane).ClosestParameter(testPoint, u, v))
  {
    return false;
  }
  double dist = (m_plane).DistanceTo(testPoint);
  if ((std::abs(u) < 1e-64) && (std::abs(v) < 1e-64))
  {
    if (dist >= 0)
    {
      latitudeRadians = 0.5 * 3.14159265358979323846;
    }
    else
    {
      latitudeRadians = -0.5 * 3.14159265358979323846;
    }
    return true;
  }
  longitudeRadians = std::atan2(v, u);
  if (longitudeRadians < 0.0)
  {
    longitudeRadians = 2.0 * 3.14159265358979323846 + longitudeRadians;
  }
  if (dist > 1e-64)
  {
    latitudeRadians = 0.5 * 3.14159265358979323846 - BND_Vector3dX::VectorAngle((m_plane).ZAxis(), testPoint - (m_plane).Origin());
  }
  else
  {
    if (dist < -1e-64)
    {
      latitudeRadians = -0.5 * 3.14159265358979323846 + BND_Vector3dX::VectorAngle(-(m_plane).ZAxis(), testPoint - (m_plane).Origin());
    }
  }
  return true;
}

