bool BND_TransformX::IsZero()
{
  for (int i = 0; i < 4; i++)
  {
    for (int j = 0; j < 4; j++)
    {
      if (3 == i && 3 == j)
      {
        break;
      }
      if (get_Item(i, j) != 0.0)
      {
        return false;
      }
    }
  }
  return !std::isnan(m_33) && !std::isinf(m_33);
}

bool BND_TransformX::IsZero4x4()
{
