bool BND_CylinderX::Transform(BND_TransformX xform)
{
  BND_CircleX c = m_basecircle;
  bool rc = (c).Transform(xform);
  if (rc)
  {
    BND_Point3dX p = ((m_basecircle).Plane()).Origin();
    BND_Vector3dX z = ((m_basecircle).Plane()).ZAxis();
    BND_Point3dX from = p + m_height1 * z;
    BND_Point3dX to = p + m_height2 * z;
    (from).Transform(xform);
    (to).Transform(xform);
    BND_Vector3dX v = to - from;
    rc = (v).IsTiny() || ((c).Normal()).IsParallelTo(v, 1e-6) != 0;
    if (rc)
    {
      m_basecircle = c;
      m_height1 = ((m_basecircle).Plane()).DistanceTo(from);
      m_height2 = ((m_basecircle).Plane()).DistanceTo(to);
    }
  }
  return rc;
}

