BND_BoxX::BND_BoxX(BND_PlaneX basePlane, const std::vector<BND_Point3dX>& points)
{
  m_dx = BND_IntervalX(+1, -1);
  m_dy = BND_IntervalX(0, 0);
  m_dz = BND_IntervalX(0, 0);
  m_plane = basePlane;
  if (!(m_plane).IsValid())
  {
    return;
  }
  if (points.empty())
  {
    return;
  }
  double x0 = std::numeric_limits<double>::max();
  double x1 = std::numeric_limits<double>::lowest();
  double y0 = std::numeric_limits<double>::max();
  double y1 = std::numeric_limits<double>::lowest();
  double z0 = std::numeric_limits<double>::max();
  double z1 = std::numeric_limits<double>::lowest();
  int point_count = 0;
  for (BND_Point3dX pt : points)
  {
    if (!(pt).IsValid())
    {
      continue;
    }
    point_count++;
    BND_Point3dX pt_mapped;
    (m_plane).RemapToPlaneSpace(pt, pt_mapped);
    x0 = RH3DM_Min(x0, (pt_mapped).m_x);
    x1 = RH3DM_Max(x1, (pt_mapped).m_x);
    y0 = RH3DM_Min(y0, (pt_mapped).m_y);
    y1 = RH3DM_Max(y1, (pt_mapped).m_y);
    z0 = RH3DM_Min(z0, (pt_mapped).m_z);
    z1 = RH3DM_Max(z1, (pt_mapped).m_z);
  }
  if (point_count == 0)
  {
    return;
  }
  m_dx = BND_IntervalX(RH3DM_Min(x0, x1), RH3DM_Max(x0, x1));
  m_dy = BND_IntervalX(RH3DM_Min(y0, y1), RH3DM_Max(y0, y1));
  m_dz = BND_IntervalX(RH3DM_Min(z0, z1), RH3DM_Max(z0, z1));
}

