double BND_BoxX::Area()
{
  if (!IsValid())
  {
    return RH3DM_RhinoMath::UnsetValue;
  }
  double dx = std::abs((m_dx).Length());
  double dy = std::abs((m_dy).Length());
  double dz = std::abs((m_dz).Length());
  double x_a = 2.0 * dx * dz;
  double y_a = 2.0 * dy * dz;
  double z_a = 2.0 * dx * dy;
  return x_a + y_a + z_a;
}

