BND_Point3dX BND_BoxX::ClosestPoint(BND_Point3dX point, bool includeInterior)
{
  if (!IsValid())
  {
    return BND_Point3dX::Unset();
  }
  BND_Point3dX pt;
  if (!(m_plane).RemapToPlaneSpace(point, pt))
  {
    return BND_Point3dX::Unset();
  }
  auto bbox = BND_BoundingBoxX(BND_Point3dX((m_dx).T0(), (m_dy).T0(), (m_dz).T0()), BND_Point3dX((m_dx).T1(), (m_dy).T1(), (m_dz).T1()));
  auto c = (bbox).ClosestPoint(pt, includeInterior);
  if (!(c).IsValid())
  {
    return BND_Point3dX::Unset();
  }
  return (m_plane).PointAt((c).X(), (c).Y()) + (m_plane).Normal() * (c).Z();
}

BND_Point3dX BND_BoxX::FurthestPoint(BND_Point3dX point)
{
  if (!IsValid())
  {
    return BND_Point3dX::Unset();
  }
  BND_Point3dX pt;
  if (!(m_plane).RemapToPlaneSpace(point, pt))
  {
    return BND_Point3dX::Unset();
  }
  double x = (pt).m_x;
  double y = (pt).m_y;
  double z = (pt).m_z;
  x = (x < (m_dx).Mid() ? (m_dx).T1() : (m_dx).T0());
  y = (y < (m_dy).Mid() ? (m_dy).T1() : (m_dy).T0());
  z = (z < (m_dz).Mid() ? (m_dz).T1() : (m_dz).T0());
  return (m_plane).PointAt(x, y, z);
}

