  (m_dx).set_T0((m_dx).T0() - (xAmount));
  (m_dx).set_T1((m_dx).T1() + (xAmount));
  (m_dy).set_T0((m_dy).T0() - (yAmount));
  (m_dy).set_T1((m_dy).T1() + (yAmount));
  (m_dz).set_T0((m_dz).T0() - (zAmount));
  (m_dz).set_T1((m_dz).T1() + (zAmount));
}

