bool BND_BoxX::Contains(BND_BoundingBoxX box, bool strict)
{
  if (!(box).IsValid() || !IsValid())
  {
    return false;
  }
  std::vector<BND_Point3dX> c = (box).GetCorners();
  if (c.empty() || ((int)c.size()) < 8)
  {
    return false;
  }
  for (int i = 0; i < ((int)c.size()); i++)
  {
    if (!Contains(c[i], strict))
    {
      return false;
    }
  }
  return true;
}

