  {
    return false;
  }
  for (int i = 0; i < ((int)corners.size()); i++)
  {
    (corners[i]).Transform(xform);
  }
  if (!(m_plane).Transform(xform))
  {
    return false;
  }
  auto pts = std::vector<BND_Point3dX>(((int)corners.size()));
  for (int i = 0; i < ((int)corners.size()); i++)
  {
    (m_plane).RemapToPlaneSpace(corners[i], pts[i]);
  }
  double x0 = 0.25 * ((pts[0]).m_x + (pts[3]).m_x + (pts[4]).m_x + (pts[7]).m_x);
  double x1 = 0.25 * ((pts[1]).m_x + (pts[2]).m_x + (pts[5]).m_x + (pts[6]).m_x);
  double y0 = 0.25 * ((pts[0]).m_y + (pts[1]).m_y + (pts[4]).m_y + (pts[5]).m_y);
  double y1 = 0.25 * ((pts[2]).m_y + (pts[3]).m_y + (pts[6]).m_y + (pts[7]).m_y);
  double z0 = 0.25 * ((pts[0]).m_z + (pts[1]).m_z + (pts[2]).m_z + (pts[3]).m_z);
  double z1 = 0.25 * ((pts[4]).m_z + (pts[5]).m_z + (pts[6]).m_z + (pts[7]).m_z);
  m_dx = BND_IntervalX(RH3DM_Min(x0, x1), RH3DM_Max(x0, x1));
  m_dy = BND_IntervalX(RH3DM_Min(y0, y1), RH3DM_Max(y0, y1));
  m_dz = BND_IntervalX(RH3DM_Min(z0, z1), RH3DM_Max(z0, z1));
  return true;
}

void BND_BoxX::RepositionBasePlane(BND_Point3dX origin)
{
