  BND_Point3dX pp;
  (m_plane).RemapToPlaneSpace(origin, pp);
  (m_dx).set_T0((m_dx).T0() - ((pp).m_x));
  (m_dx).set_T1((m_dx).T1() - ((pp).m_x));
  (m_dy).set_T0((m_dy).T0() - ((pp).m_y));
  (m_dy).set_T1((m_dy).T1() - ((pp).m_y));
  (m_dz).set_T0((m_dz).T0() - ((pp).m_z));
  (m_dz).set_T1((m_dz).T1() - ((pp).m_z));
